def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or (s.get('last_result_was_error') and s.get('last_error_kind') in ('unknown_col', 'syntax')):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_check'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['ready_to_commit_candidate'] = True
    if p.get('remaining_rounds_low') and p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        stage = 'ready_to_commit_candidate'
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage') or ''
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema recovery: use SHOW TABLES, then DESCRIBE the exact table name with backticks if it contains spaces or reserved words. In MySQL, wrap such column names in backticks, not double quotes.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT recovery: inspect a few sample rows or distinct values for the filtered columns, then relax one predicate or adjust case, spacing, punctuation, or numeric/text casting before retrying.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL loop: change strategy instead of rerunning the same query. Probe schema, sample values, or predicates, and simplify the WHERE clause to isolate the failing condition.'
    elif stage == 'text_numeric_check':
        msg = 'Text numerics: many DBBench columns are TEXT. For ranking, sorting, or aggregation, cast cleaned numeric expressions to SIGNED or DECIMAL rather than comparing raw text.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. Use MySQL backticks for awkward identifiers and preserve the requested literal text exactly, including commas, spaces, percent signs, and newlines.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: an empty tool result can still mean the data-changing statement ran. If rounds allow, SELECT the affected row(s) to verify exact stored values, then commit a brief completion answer.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (p.get('mutation_not_attempted') or nb.get('stage') == 'mutation_needs_execution')):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested cell values or rows.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted') and not p.get('remaining_rounds_low'):
        return {'kind': 'block_and_prompt', 'message': 'This is a database mutation task. Execute the INSERT, UPDATE, or DELETE first; the final text alone will not change the database state.'}
    return None
